/**
 * Date math is done on whole UTC days so results never shift with the
 * device timezone or DST. Dates are ISO 'YYYY-MM-DD' strings throughout.
 */
const MS_PER_DAY = 86_400_000;

export function isIsoDate(value        )          {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  return toUtcMillis(value) !== null;
}

function toUtcMillis(iso        )                {
  const parts = iso.split('-').map(Number);
  if (parts.length !== 3 || parts.some((n) => !Number.isFinite(n))) return null;
  const [y, m, d] = parts;
  // `Date.UTC` (per spec) silently maps a two-digit year 0-99 to 1900+year
  // - Date.UTC(47, ...) means 1947, not year 47 - which would make a
  // 4-digit "0047-09-01" round-trip as 1947 and get wrongly rejected below.
  // `setUTCFullYear` takes the year literally, with no such special case.
  const probe = new Date(0);
  probe.setUTCFullYear(y, m - 1, d);
  const ms = probe.getTime();
  const back = new Date(ms);
  // Rejects things like 2026-02-31 that Date.UTC would silently roll over.
  if (
    back.getUTCFullYear() !== y ||
    back.getUTCMonth() !== m - 1 ||
    back.getUTCDate() !== d
  ) {
    return null;
  }
  return ms;
}

export function addDays(iso        , days        )         {
  const ms = toUtcMillis(iso);
  if (ms === null) throw new Error(`not an ISO date: ${iso}`);
  return new Date(ms + days * MS_PER_DAY).toISOString().slice(0, 10);
}

export function daysBetween(fromIso        , toIso        )         {
  const a = toUtcMillis(fromIso);
  const b = toUtcMillis(toIso);
  if (a === null || b === null) throw new Error('not an ISO date');
  return Math.round((b - a) / MS_PER_DAY);
}

